+    struct DeliveryTemplate {
+        requests: Vec<usize>,
+        units: u64,
+        bits: u64,
+    }
+
+    fn delivery_function(index: usize) -> Function {
+        if index == 0 {
+            Function::Quantile
+        } else {
+            Function::Fraction
+        }
+    }
+
+    fn delivery_template(group: usize, function: Function) -> DeliveryTemplate {
+        let engine = EngineAccounting::default();
+        let account = engine.query();
+        let control = Control::default();
+        let upper = (1u64 << group) as f64;
+        let mut bounds = [
+            Bound {
+                upper_bound: f64::INFINITY,
+                ordinal: 1,
+            },
+            Bound {
+                upper_bound: upper,
+                ordinal: 0,
+            },
+        ];
+        let operation = match function {
+            Function::Quantile => Operation::Quantile(0.5),
+            Function::Fraction => Operation::Fraction(0.0, 1.0),
+            Function::Quantiles => unreachable!(),
+        };
+        let mut replay = Replay::new(operation, &mut bounds, &account, || {
+            control.check()?;
+            account.work(1);
+            Ok::<_, Interrupted>(())
+        })
+        .unwrap();
+        let mut requests = Vec::new();
+        let (units, bits) = loop {
+            match replay
+                .next(&bounds, || {
+                    control.check()?;
+                    account.work(1);
+                    Ok::<_, Interrupted>(())
+                })
+                .unwrap()
+            {
+                classic_replay::Action::Count(row) => {
+                    assert!(row < 2);
+                    requests.push(row);
+                    replay.receive(
+                        (row + 1) as f64,
+                        Some(crate::statistics::OwnedSamples::new(&account, 1)),
+                    );
+                }
+                classic_replay::Action::Done(parts) => {
+                    let expected = if matches!(function, Function::Quantile) {
+                        upper
+                    } else {
+                        0.5 / upper
+                    };
+                    assert_eq!(parts.result.value.to_bits(), expected.to_bits());
+                    assert!(!parts.result.forced_monotonicity);
+                    break (parts.samples.units(), parts.result.value.to_bits());
+                }
+            }
+        };
+        drop(replay);
+        assert_eq!(account.current_samples(), 0);
+        account.snapshot().assert_memory_released();
+        DeliveryTemplate {
+            requests,
+            units,
+            bits,
+        }
+    }
+
+    fn delivery_present(group: usize, count: usize, population: usize) -> bool {
+        match population {
+            0 => true,
+            1 => group % 2 == 0,
+            2 => group + 1 == count,
+            3 => group >= count.saturating_sub(4),
+            _ => unreachable!(),
+        }
+    }
+
+    fn delivery_plan(
+        count: usize,
+        population: usize,
+        delayed: bool,
+        certified: bool,
+        control: &Control,
+        account: &QueryAccounting,
+    ) -> Plan {
+        let mut rows = AccountedVec::new(account, MemoryKind::Workspace);
+        for group in 0..count {
+            let name = format!("{:016}", count - 1 - group);
+            let bound = format!("{:020}", 1u64 << group);
+            for bound in [bound.as_bytes(), b"+Inf"] {
+                row(
+                    &mut rows,
+                    1,
+                    &[(b"__name__", b"h"), (b"a", name.as_bytes()), (b"le", bound)],
+                    account,
+                );
+            }
+        }
+        if population >= 2 {
+            for group in 0..count {
+                if !delivery_present(group, count, population) {
+                    let name = format!("{:016}", count - 1 - group);
+                    row(
+                        &mut rows,
+                        2,
+                        &[(b"__name__", b"h"), (b"a", name.as_bytes())],
+                        account,
+                    );
+                }
+            }
+        }
+        let mut plan = Plan::new(rows, control, account).unwrap();
+        assert_eq!(plan.groups.len(), count);
+        let mut cache = Cache::new(account);
+        let mut outputs = AccountedVec::new(account, MemoryKind::Workspace);
+        for group in (0..count).rev() {
+            let name = format!("{:016}", count - 1 - group);
+            let mut fields: Vec<(&[u8], &[u8])> = Vec::new();
+            if delayed {
+                fields.push((b"__name__", b"h"));
+            }
+            fields.push((b"a", name.as_bytes()));
+            row(&mut outputs, 1, &fields, account);
+            let output = outputs.last_mut().unwrap();
+            output.drop_name = true;
+            output.hash = label_hash::full(&output.labels, control, account).unwrap();
+            cache.bindings.push(Binding {
+                key: BindingKey::Classic(group),
+                occurrence: 0,
+                labels: output
+                    .labels
+                    .copy_checked(account, MemoryKind::Workspace, control)
+                    .unwrap(),
+            });
+        }
+        plan.finish(cache);
+        if certified {
+            let sources: Vec<_> = (0..count).collect();
+            plan.certify_ordered_streaming(&outputs, &sources, control, account)
+                .unwrap();
+        }
+        assert_eq!(plan.streams_ordered(), certified && count != 0);
+        plan
+    }
