+    struct DeliveryContext<'a> {
+        count: usize,
+        population: usize,
+        function: Function,
+        options: EvaluationOptions,
+        selected: Option<&'a [usize]>,
+        preparation: Option<Preparation<'a>>,
+    }
+
+    fn delivery_start<'a>(
+        plan: &'a Plan,
+        context: &DeliveryContext<'a>,
+        active_ids: Option<&[usize]>,
+        control: &Control,
+        account: &QueryAccounting,
+    ) -> Step<'a> {
+        let DeliveryContext {
+            count,
+            population,
+            function,
+            options,
+            selected,
+            preparation,
+        } = *context;
+        let mut step = distribution_step(plan, account);
+        step.arguments.function = function;
+        step.arguments.scalar_count = if matches!(function, Function::Fraction) {
+            2
+        } else {
+            1
+        };
+        step.parameters[0] = Some(if matches!(function, Function::Fraction) {
+            0.0
+        } else {
+            0.5
+        });
+        step.parameters[1] = Some(1.0);
+        step.selected = selected;
+        if preparation.is_some() {
+            step.notes = Some(AnnotationBuilder::new(account));
+        }
+        for group in (0..count).rev() {
+            if (population == 1 && !delivery_present(group, count, population))
+                || active_ids.is_some_and(|ids| !ids.contains(&group))
+            {
+                continue;
+            }
+            for row in [2 * group + 1, 2 * group] {
+                step.active.push(Active {
+                    row,
+                    kind: 1,
+                    skip: false,
+                });
+            }
+        }
+        for row in 2 * count..plan.rows.len() {
+            step.active.push(Active {
+                row,
+                kind: 2,
+                skip: false,
+            });
+        }
+        step.begin(options, preparation, b"", control, account)
+            .unwrap();
+        assert!(matches!(step.phase, Phase::Choose));
+        for active in &*step.groups {
+            let productive = delivery_present(active.group, count, population);
+            assert_eq!(active.skip, !productive);
+            let bounds = &step.bounds[active.bounds.clone()];
+            if productive {
+                assert_eq!(bounds.len(), 2);
+                assert_eq!(
+                    (bounds[0].upper_bound.to_bits(), bounds[0].ordinal),
+                    (f64::INFINITY.to_bits(), 2 * active.group + 1)
+                );
+                assert_eq!(
+                    (bounds[1].upper_bound.to_bits(), bounds[1].ordinal),
+                    (((1u64 << active.group) as f64).to_bits(), 2 * active.group)
+                );
+            } else {
+                assert!(bounds.is_empty());
+            }
+        }
+        assert_eq!(
+            step.groups.len(),
+            active_ids.map_or_else(
+                || (0..count)
+                    .filter(|group| population != 1 || delivery_present(*group, count, population))
+                    .count(),
+                <[usize]>::len
+            )
+        );
+        step
+    }
