+    fn delivery_drive<'a>(
+        step: &mut Step<'a>,
+        context: &DeliveryContext<'a>,
+        expected: &[(usize, usize)],
+        templates: &[DeliveryTemplate],
+        control: &Control,
+        account: &QueryAccounting,
+    ) -> Result<DeliveryObserved, EvaluationError> {
+        let count = context.count;
+        let options = context.options;
+        let preparation = context.preparation;
+        let start = account.snapshot().work;
+        let mut first_child = None;
+        let mut requests = Vec::new();
+        let mut outputs = 0;
+        loop {
+            match step.advance(NodeId(0), options, preparation, b"", control, account)? {
+                Action::Child { argument, ordinal } => {
+                    assert_eq!(argument, step.arguments.function.vector_argument());
+                    let row = *ordinal.expect("count request has a source ordinal");
+                    assert!(row < 2 * count);
+                    first_child.get_or_insert(account.snapshot().work - start);
+                    requests.push(row);
+                    let labels = step.plan.rows[row].labels.copy_checked(
+                        account,
+                        MemoryKind::Workspace,
+                        control,
+                    )?;
+                    step.receive(
+                        EvaluatedSample {
+                            ordinal: row,
+                            labels: labels.into(),
+                            value: OwnedValue::Float((row % 2 + 1) as f64),
+                            float_samples: Some(crate::statistics::OwnedSamples::new(account, 1)),
+                            source_time_ms: options.time_ms,
+                            source_start_time_ms: 0,
+                            drop_name: false,
+                        },
+                        control,
+                        account,
+                    )?;
+                }
+                Action::Sample(sample) => {
+                    let (ordinal, group) = expected[outputs];
+                    assert_eq!(sample.ordinal, ordinal);
+                    assert!(
+                        matches!(sample.value, OwnedValue::Float(value) if value.to_bits() == templates[group].bits)
+                    );
+                    assert_eq!(
+                        sample.float_samples.as_ref().unwrap().units(),
+                        templates[group].units
+                    );
+                    assert_eq!(sample.source_time_ms, options.time_ms);
+                    assert_eq!(sample.source_start_time_ms, 0);
+                    assert!(sample.drop_name);
+                    let name = format!("{:016}", count - 1 - group);
+                    let mut labels: Vec<(&[u8], &[u8])> = Vec::new();
+                    if options.delayed_name_removal {
+                        labels.push((b"__name__", b"h"));
+                    }
+                    labels.push((b"a", name.as_bytes()));
+                    assert_eq!(
+                        sample
+                            .labels
+                            .0
+                            .iter()
+                            .map(|label| (&*label.name, &*label.value))
+                            .collect::<Vec<_>>(),
+                        labels
+                    );
+                    outputs += 1;
+                    drop(sample);
+                    assert_eq!(account.current_samples(), 0);
+                }
+                Action::Done(notes) => {
+                    assert_eq!(notes.is_some(), preparation.is_some());
+                    if let Some(notes) = notes {
+                        assert!(notes.finish().is_empty());
+                    }
+                    break;
+                }
+            }
+        }
+        assert_eq!(outputs, expected.len());
+        let expected_requests: Vec<_> = expected
+            .iter()
+            .flat_map(|(_, group)| {
+                templates[*group]
+                    .requests
+                    .iter()
+                    .map(move |row| 2 * group + row)
