+            .collect();
+        assert_eq!(requests, expected_requests);
+        assert_eq!(account.current_samples(), 0);
+        Ok(DeliveryObserved {
+            work: account.snapshot().work - start,
+            first_child,
+            requests,
+            outputs,
+        })
+    }
